start=date(2023,12,1); end=date(2026,10,1); sessions=[]; d=start
while d<=end:
    ds=d.isoformat(); year=str(d.year)
    if ds in special:
        item=special[ds]; typ="SPECIAL"; intervals=item["intervals"]; sids=item["source_ids"]; note=item["note"]
    elif ds in hol.get(year,[]):
        typ="HOLIDAY"; intervals=[]; sids=holiday_sources.get(year,[])+holiday_specific_sources.get(ds,[]); note="NSE-published CM holiday or later amendment."
    elif d.weekday()>=5:
        typ="WEEKEND_CLOSED"; intervals=[]; sids=["NSE_TIMINGS"]; note="Weekly closure default; special dates have explicit circular overrides."
    else:
        typ="REGULAR"; intervals=[{"start":"09:15","end":"15:30"}]; sids=list(dict.fromkeys(holiday_sources.get(year,[])+["NSE_TIMINGS"])); note="Regular weekday under annual CM calendar and published regular-market hours."
    sessions.append({"date":ds,"segment":"CM","timezone":"Asia/Kolkata","session_type":typ,"normal_market_intervals":intervals,"special_session":typ=="SPECIAL","verification_status":"VERIFIED","source_ids":sids,"note":note})
    d+=timedelta(days=1)
